result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/audit-js/audit_js/core.py", "content": """"Core lockfile auditing logic.

The advisory table maps package name -> list of vulnerable versions.
Dependency paths are reconstructed by walking lock 'packages' keys of the
form ``node_modules/a/node_modules/b`` (lockfileVersion 3 layout).
"""

from __future__ import annotations

import json
import os
from dataclasses import dataclass
from typing import Dict, List, Optional

# Inline advisory database: package name -> vulnerable versions.
ADVISORIES: Dict[str, List[str]] = {
    "lodash": ["4.17.20"],
    "minimist": ["1.2.5", "0.0.8"],
    "node-fetch": ["2.6.6"],
}

ROOT = "(root)"


@dataclass(frozen=True)
class Finding:
    """A single vulnerable package occurrence in the dependency tree."""

    name: str
    version: str
    # Dependency chain from the root package down to the vulnerable package,
    # e.g. ["(root)", "my-cli", "request", "node-fetch"].
    path: List[str]
    # Raw lockfile key that produced this finding,
    # e.g. "node_modules/my-cli/node_modules/node-fetch".
    lock_key: str

    def format(self) -> str:
        return (
            f"{self.name}@{self.version} is vulnerable "
            f"(via {self.name + ' <- ' if False else ''}"
            f"{' -> '.join(self.path)}; locked at {self.lock_key})"
        )


def _name_from_key(lock_key: str) -> str:
    """Extract the package name from a lockfile key like
    ``node_modules/a/node_modules/@scope/b`` -> ``@scope/b``."""
    last_segment = lock_key.split("/node_modules/")[-1]
    return last_segment[len("node_modules/"):] if last_segment.startswith(
        "node_modules/"
    ) else last_segment


def _path_from_key(lock_key: str) -> List[str]:
    """Turn ``node_modules/a/node_modules/b`` into ``["(root)", "a", "b"]``."""
    parts = [p for p in lock_key.split("/") if p]
    chain: List[str] = [ROOT]
    i = 0
    while i < len(parts):
        if parts[i] == "node_modules":
            i += 1
            continue
        chain.append(parts[i])
        i += 1
    return chain


def load_json(path: str) -> dict:
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def flatten_packages(lock: dict) -> Dict[str, str]:
    """Flatten every resolved package version from the lock's ``packages`` map.

    Returns ``{package_name: version}``. The root entry (key ``""``) and any
    entries lacking a version (links/workspace stubs) are skipped. Later
    duplicate names keep their first occurrence -- in practice a
    lockfileVersion 3 tree has one entry per unique key, and duplicates of the
    same name at different depths are all reported by :func:`audit` instead.
    """
    packages = lock.get("packages") or {}
    flat: Dict[str, str] = {}
    for key, meta in packages.items():
        if not key:  # root package entry
            continue
        if not isinstance(meta, dict):
            continue
        version = meta.get("version")
        if not version:
            continue  # links / workspace placeholders have no version
        flat.setdefault(_name_from_key(key), version)
    return flat


def audit(
    package_lock: dict,
    advisories: Optional[Dict[str, List[str]]] = None,
) -> List[Finding]:
    """Return one :class:`Finding` per (vulnerable package occurrence, path)."""
    advisories = advisories if advisories is not None else ADVISORIES
    findings: List[Finding] = []
    for key, meta in sorted((package_lock.get("packages") or {}).items()):
        if not key or not isinstance(meta, dict):
            continue
        version = meta.get("version")
        if not version:
            continue
        name = _name_from_key(key)
        vuln_versions = advisories.get(name)
        if vuln_versions and version in vuln_versions:
            findings.append(
                Finding(
                    name=name,
                    version=version,
                    path=_path_from_key(key),
                    lock_key=key,
                )
            )
    return findings


def audit_directory(
    directory: str,
    advisories: Optional[Dict[str, List[str]]] = None,
) -> List[Finding]:
    """Load ``package.json`` + ``package-lock.json`` from *directory* and audit.

    Raises :class:`AuditError` on missing/malformed inputs.
    """
    pkg_path = os.path.join(directory, "package.json")
    lock_path = os.path.join(directory, "package-lock.json")
    for p in (pkg_path, lock_path):
        if not os.path.isfile(p):
            raise AuditError(f"missing required file: {p}")
    try:
        manifest = load_json(pkg_path)
        lock = load_json(lock_path)
    except json.JSONDecodeError as exc:
        raise AuditError(f"invalid JSON: {exc}") from exc

    if lock.get("lockfileVersion") != 3:
        raise AuditError(
            f"unsupported lockfileVersion {lock.get('lockfileVersion')!r}; expected 3"
        )
    if "packages" not in lock:
        raise AuditError("package-lock.json has no 'packages' map")
    # Sanity check that manifest parses as an object with a deps section we ignore.
    if not isinstance(manifest, dict):
        raise AuditError("package.json is not a JSON object")

    return audit(lock, advisories)


class AuditError(Exception):
    """Raised for unusable input files."""
